\":{\"value\":0,\"unit\":\"px\"},\"radius\":{\"right\":{\"value\":0,\"unit\":\"px\"},\"left\":{\"value\":0,\"unit\":\"px\"}}},\"right\":{\"style\":\"none\",\"width\":{\"value\":0,\"unit\":\"px\"}},\"left\":{\"style\":\"none\",\"width\":{\"value\":0,\"unit\":\"px\"}}},\"padding\":{\"top\":{\"unit\":\"px\",\"value\":\"15\"},\"bottom\":{\"unit\":\"px\",\"value\":\"15\"},\"left\":{\"unit\":\"px\",\"value\":\"30\"},\"right\":{\"unit\":\"px\",\"value\":\"30\"}},\"states\":{\"hover\":{\"background\":{\"color\":\"#2163d3\"}}},\"background\":{\"color\":\"rgba(var(--kubio-color-1),1)\"}},\"icon\":{\"size\":{\"unit\":\"px\",\"value\":\"14\"},\"margin\":{\"left\":{\"value\":10,\"unit\":\"px\"},\"right\":{\"value\":0,\"unit\":\"px\"}}}}},\"hash\":\"2827807c\"},\"link\":{\"value\":\"https://ipkorotkov.online/services/\",\"typeOpenLink\":\"sameWindow\",\"noFollow\":false,\"lightboxMedia\":\"\"},\"preserveSpace\":{\"text\":false},\"icon\":{\"name\":\"font-awesome/arrow-right\"}} -->\nПодробнее\n<!-- /wp:kubio/button -->\n<!-- /wp:kubio/buttongroup -->\n<!-- /wp:kubio/column -->\n\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"ETiZbrj044\",\"hash\":\"e5925f80\",\"style\":{\"descendants\":{\"inner\":{\"background\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"textAlign\":\"left\"}}},\"props\":{\"layout\":{\"horizontalInnerGap\":3,\"verticalInnerGap\":3},\"media\":{\"tablet\":{\"layout\":{\"verticalInnerGap\":3}}}}}} -->\n<!-- wp:kubio/heading {\"kubio\":{\"styleRef\":\"yQNznI0LN\",\"style\":{\"descendants\":{\"text\":{\"typography\":{\"color\":\"rgba(var(--kubio-color-1),1)\"}}}},\"props\":{\"level\":5,\"fancy\":{\"fancyRotatingWords\":\"awesome\\namazing\\nimpressive\"}},\"hash\":\"2f8fec72\"}} -->\n.2\n<!-- /wp:kubio/heading -->\n\n<!-- wp:kubio/heading {\"kubio\":{\"styleRef\":\"XGy1Q5Xmg\",\"props\":{\"level\":4,\"fancy\":{\"fancyRotatingWords\":\"awesome\\namazing\\nimpressive\"}},\"hash\":\"UgTZbGkBy\",\"style\":{\"descendants\":{\"text\":{\"media\":{\"tablet\":{\"typograph