in\":{\"left\":{\"value\":10,\"unit\":\"px\"},\"right\":{\"value\":0,\"unit\":\"px\"}}}}},\"hash\":\"fthAk7ZIy\"},\"link\":{\"value\":\"https://ipkorotkov.online/services/\",\"typeOpenLink\":\"sameWindow\",\"noFollow\":false,\"lightboxMedia\":\"\"},\"preserveSpace\":{\"text\":false},\"icon\":{\"name\":\"font-awesome/arrow-right\"}} -->\nНачните сегодня\n<!-- /wp:kubio/button -->\n<!-- /wp:kubio/buttongroup -->\n<!-- /wp:kubio/column -->\n\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"mwWrU6lqjw\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":50,\"unit\":\"%\"}}}}},\"hash\":\"dd085cc4\",\"props\":{\"media\":{\"tablet\":{\"layout\":{\"verticalAlign\":\"center\"}}}}}} -->\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"Q6vWysLq1\",\"hash\":\"f6d0d358\"},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/10/StockSnap-TDAU1ERCD4.jpg\",\"id\":76} /-->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n<!-- /wp:kubio/section -->\n\n<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"LTlIa4_ic_\",\"style\":{\"descendants\":{\"outer\":{\"background\":{\"color\":\"rgba(var(--kubio-color-4),1)\"}}}},\"hash\":\"6140d0t5w9\"},\"attrs\":{\"name\":\"features\"},\"anchor\":\"features\"} -->\n<!-- wp:kubio/row {\"kubio\":{\"styleRef\":\"5M_Geo1XG\",\"props\":{\"meta\":{\"isHeader\":true},\"layout\":{\"itemsPerRow\":1,\"equalWidth\":false,\"equalHeight\":true,\"horizontalAlign\":\"start\"},\"media\":{\"mobile\":{\"layout\":{\"horizontalGap\":3,\"verticalGap\":3}}}},\"hash\":\"403ee3c2\"}} -->\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"2JXqUoEQ-q\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":80,\"unit\":\"%\"}},\"media\":{\"tablet\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":100,\"unit\":\"%\"}}}}}}},\"hash\":\"6d6814f7\",\"style\":{\"descendants\":{\"inner\":{\"textAlign\":\"left\"}}},\"props\":{\"layout\":{\"verticalAlign\":\"center\"}}