 /-->\n\n<!-- wp:kubio/heading {\"kubio\":{\"styleRef\":\"9RhLVt9Uz\",\"props\":{\"level\":6,\"fancy\":{\"fancyRotatingWords\":\"awesome\\namazing\\nimpressive\"}},\"hash\":\"ClNY9rmjX\"}} -->\nсайт\n<!-- /wp:kubio/heading -->\n<!-- /wp:kubio/column -->\n\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"UQH9-uA_cm\",\"style\":{\"descendants\":{\"inner\":{\"textAlign\":\"left\"}}},\"props\":{\"layout\":{\"vSpace\":{\"value\":0,\"unit\":\"px\"}},\"media\":{\"mobile\":{\"layout\":{\"horizontalInnerGap\":0,\"verticalInnerGap\":3}}}},\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":50,\"unit\":\"%\"}},\"media\":{\"mobile\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":100,\"unit\":\"%\"}}}}}}},\"hash\":\"5d4552c4\"}} -->\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"CBFlNtGgj\",\"hash\":\"kUGyRXqoH\",\"style\":{\"descendants\":{\"outer\":{\"padding\":{\"bottom\":{\"value\":20,\"unit\":\"px\"}}}}}},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/10/tWx8kkOSCQVRkhCur9cpivGGm6HLhOPrTKAHV_PeL8zolClpkPgBnqsXW7Xw9v43vSVtQnGD7UaqD7Esxwt2NsqQ.jpg\",\"id\":327,\"sizeSlug\":\"full\"} /-->\n\n<!-- wp:kubio/heading {\"kubio\":{\"styleRef\":\"9RhLVt9Uz\",\"props\":{\"level\":6,\"fancy\":{\"fancyRotatingWords\":\"awesome\\namazing\\nimpressive\"}},\"hash\":\"XxiZzRS22c\"}} -->\nИнтернет- магазин\n<!-- /wp:kubio/heading -->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n\n<!-- wp:html -->\n<style>\n  .featured-project {\n    position: relative;\n    margin: 60px 0;\n    border-radius: 24px;\n    overflow: hidden;\n    background: linear-gradient(135deg, #0a0e1a 0%, #0f1524 50%, #1a1f35 100%);\n    border: 1px solid rgba(127, 227, 201, 0.15);\n    transition: all 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);\n    cursor: pointer;\n    text-decoration: none;\n    display: block;\n    color: inherit;\n  }\n  .featured-project:hover {\n    transform: translateY(-8px);\n    border-color: rgba(127, 227, 201, 0.4);\n    box-shadow: 0 40px 80px -20px rgba(127, 227, 201, 0.25);\n  }\n  .fp-inner {\n    display: grid;\n    grid-template-columns: 1.2fr 1fr;\n    min-height: 420px;\n  }\n  .fp-visual {\n    position: relative;\n    background: \n      radial-gradient(circle at 30% 50%, rgba(127,227,201,0.2), transparent 50%),\n      radial-gradient(circle at 70% 80%, rgba(184,232,255,0.15), transparent 50%);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n  }\n  .fp-visual::before {\n    content: \'\';\n    position: absolute;\n    inset: 0;\n    background-image: \n      linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),\n      linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);\n    background-size: 40px 40px;\n    mask-image: radial-gradient(circle at center, black 40%, transparent 80%);\n  }\n  .fp-mockup {\n    position: relative;\n    width: 80%;\n    height: 70%;\n    background: linear-gradient(135deg, rgba(127,227,201,0.1), rgba(184,232,255,0.05));\n    border: 1px solid rgba(255,255,255,0.1);\n    border-radius: 12px;\n    overflow: hidden;\n    box-shadow: 0 30px 60px rgba(0,0,0,0.4);\n    transform: perspective(1000px) rotateY(-8deg) rotateX(4deg);\n    transition: transform 0.5s;\n  }\n  .featured-project:hover .fp-mockup {\n    transform: perspective(1000px) rotateY(0) rotateX(0);\n  }\n  .fp-mockup-bar {\n    height: 28px;\n    background: rgba(0,0,0,0.4);\n    display: flex;\n    align-items: center;\n    padding: 0 12px;\n    gap: 6px;\n  }\n  .fp-mockup-bar span {\n    width: 9px; height: 9px; border-radius: 50%;\n  }\n  .fp-mockup-bar span:nth-child(1) { background: #ff5f57; }\n  .fp-mockup-bar span:nth-child(2) { background: #ffbd2e; }\n  .fp-mockup-bar span:nth-child(3) { background: #28ca42; }\n  .fp-mockup-content {\n    padding: 25px;\n    color: #F5F1E8;\n    font-family: \'Playfair Display\', serif;\n    font-style: italic;\n    font-size: 28px;\n    line-height: 1.2;\n  }\n  .fp-mockup-content small {\n    display: block;\n    font-family: \'Manrope\', sans-serif;\n    font-style: normal;\n    font-size: 11px;\n    letter-spacing: 3px;\n    color: #7FE3C9;\n    text-transform: uppercase;\n    margin-bottom: 10px;\n  }\n  .fp-info {\n    padding: 50px;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n  }\n  .fp-tag {\n    display: inline-flex;\n    align-items: center;\n    gap: 10px;\n    font-size: 11px;\n    letter-spacing: 3px;\n    text-transform: uppercase;\n    color: #7FE3C9;\n    margin-bottom: 20px;\n  }\n  .fp-tag::before {\n    content: \'\';\n    width: 30px; height: 1px; background: #7FE3C9;\n  }\n  .fp-title {\n    font-family: \'Playfair Display\', serif;\n    font-size: 42px;\n    font-weight: 400;\n    line-height: 1.1;\n    margin-bottom: 20px;\n    color: #F5F1E8;\n  }\n  .fp-title em {\n    color: #7FE3C9;\n    font-style: italic;\n  }\n  .fp-desc {\n    font-size: 15px;\n    line-height: 1.7;\n    color: #8A94A8;\n    margin-bottom: 30px;\n  }\n  .fp-tech {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n    margin-bottom: 30px;\n  }\n  .fp-tech span {\n    padding: 6px 14px;\n    border: 1px solid rgba(255,255,255,0.1);\n    border-radius: 50px;\n    font-size: 11px;\n    letter-spacing: 1px;\n    color: #8A94A8;\n  }\n  .fp-link {\n    display: inline-flex;\n    align-items: center;\n    gap: 12px;\n    font-size: 13px;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n    color: #7FE3C9;\n    font-weight: 600;\n    transition: gap 0.3s;\n  }\n  .featured-project:hover .fp-link { gap: 18px; }\n  .fp-link svg { width: 16px; height: 16px; }\n  \n  @media (max-width: 768px) {\n    .fp-inner { grid-template-columns: 1fr; }\n    .fp-visual { min-height: 280px; }\n    .fp-info { padding: 30px; }\n    .fp-title { font-size: 32px; }\n  }\n</style>\n\n<a href=\"https://ipkorotkov.online/lumiere/\" target=\"_blank\" class=\"f