: none !important;\n    border-radius: 6px !important;\n    font-weight: 600 !important;\n    font-size: 16px !important;\n    font-family: Arial, Helvetica, sans-serif !important;\n    text-align: center !important;\n    transition: background 0.2s ease;\n  }\n  .work-btn:hover {\n    background: #0056b3 !important;\n    color: #ffffff !important;\n  }\n</style>\n\n<div class=\"animation-wrapper\">\n  <iframe src=\"https://ipkorotkov.online/lumiere/\"\n          frameborder=\"0\"\n          scrolling=\"no\"\n          allowfullscreen\n          title=\"Анимация\">\n  </iframe>\n</div>\n\n<div style=\"text-align: center;\">\n  <a href=\"https://ipkorotkov.online/lumiere/\" target=\"_blank\" class=\"work-btn\">Открыть работу</a>\n</div>\n<!-- /wp:html -->\n<!-- /wp:kubio/section -->\n\n<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"LTlIa4_ic_\",\"style\":{\"descendants\":{\"outer\":{\"background\":{\"color\":\"rgba(var(--kubio-color-4),1)\"}}}},\"hash\":\"9uDNUlt5u\",\"props\":{\"width\":\"boxed\"}},\"attrs\":{\"name\":\"testimonials\"},\"anchor\":\"testimonials\"} -->\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"BcvHbU0JG\",\"hash\":\"pe-5EGgSdW\"},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/11/2026-11-15_04-04-04-1.png\",\"id\":547,\"sizeSlug\":\"full\"} /-->\n\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"t-KGh42MG\",\"hash\":\"h5iavElLU\"},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/11/2026-11-15_04-04-30-1.png\",\"id\":548,\"sizeSlug\":\"full\"} /-->\n\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"-iRq7RQBS\",\"hash\":\"7LG-PN8-v\"},\"link\":{\"typeOpenLink\":\"sameWindow\",\"lightboxMedia\":\"\",\"value\":\"\"},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/11/2026-11-15_04-05-17-1.png\",\"id\":549,\"sizeSlug\":\"full\"} /-->\n\n<!-- wp:kubio/spacer {\"kubio\":{\"styleRef\":\"L-MrjAHOr\",\"hash\":\"SXxr-5l70b\"}} /-->\n\n<!-- wp:kubio/image-gallery {\"kubio\":{\"styleRef\":\"CvbJRDtkO\",\"hash\":\"r8iw9nPwN\