:{\"value\":5,\"unit\":\"px\"}}},\"right\":{\"color\":\"rgba(var(--kubio-color-1),1)\",\"style\":\"solid\",\"width\":{\"value\":\"2\",\"unit\":\"px\"}},\"left\":{\"color\":\"rgba(var(--kubio-color-1),1)\",\"style\":\"solid\",\"width\":{\"value\":\"2\",\"unit\":\"px\"}}},\"padding\":{\"top\":{\"unit\":\"px\",\"value\":\"12\"},\"bottom\":{\"unit\":\"px\",\"value\":\"12\"},\"left\":{\"unit\":\"px\",\"value\":\"24\"},\"right\":{\"unit\":\"px\",\"value\":\"24\"}},\"states\":{\"hover\":{\"background\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"border\":{\"top\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"right\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"bottom\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"left\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"}}}}},\"icon\":{\"size\":{\"unit\":\"px\",\"value\":\"12\"},\"margin\":{\"left\":{\"value\":10,\"unit\":\"px\"},\"right\":{\"value\":0,\"unit\":\"px\"}}}}},\"hash\":\"yg4JIvyDA\"},\"link\":{\"value\":\"https://ipkorotkov.online/contact/\",\"typeOpenLink\":\"sameWindow\",\"noFollow\":false,\"lightboxMedia\":\"\"},\"preserveSpace\":{\"text\":false},\"icon\":{\"name\":\"font-awesome/arrow-right\"}} -->\nСвязаться\n<!-- /wp:kubio/button -->\n<!-- /wp:kubio/buttongroup -->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n\n<!-- wp:html -->\n<style>\n  .portfolio-embed {\n    max-width: 1000px;\n    margin: 40px auto;\n    font-family: \'Manrope\', -apple-system, sans-serif;\n  }\n\n  .browser-mockup {\n    background: #0a0e1a;\n    border-radius: 16px;\n    overflow: hidden;\n    border: 1px solid rgba(127, 227, 201, 0.2);\n    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6), 0 0 40px rgba(127, 227, 201, 0.08);\n    transition: transform 0.4s ease, box-shadow 0.4s ease;\n  }\n  .browser-mockup:hover {\n    transform: translateY(-5px);\n    box-shadow: 0 35px 60px -15px rgba(0, 0, 0, 0.7), 0 0 60px rgba(127, 227, 201, 0.15);\n  }\n\n  .browser-header {\n    background: #0f1524;\n    padding: 14px 20px;\n    display: flex;\n    align-items: center;\n    gap: 15px;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n  }\n  .browser-dots { display: flex; gap: 8px; }\n  .browser-dots span { width: 12px; height: 12px; border-radius: 50%; }\n  .browser-dots span:nth-child(1) { background: #ff5f57; }\n  .browser-dots span:nth-child(2) { background: #ffbd2e; }\n  .browser-dots span:nth-child(3) { background: #28ca42; }\n\n  .browser-url {\n    flex: 1;\n    background: rgba(255, 255, 255, 0.06);\n    border-radius: 8px;\n    padding: 8px 16px;\n    font-size: 13px;\n    color: #8A94A8;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .browser-url svg { width: 14px; height: 14px; stroke: #7FE3C9; }\n\n  .browser-frame {\n    width: 100%;\n    height: 70vh;\n    min-height: 550px;\n    max-height: 800px;\n    border: none;\n    display: block;\n    background: #0a0e1a;\n  }\n\n  .portfolio-action { text-align: center; margin-top: 30px; }\n  .portfolio-btn {\n    display: inline-flex !important;\n    align-items: center;\n    justify-content: center;\n    gap: 10px;\n    padding: 16px 36px !important;\n    background: linear-gradient(135deg, #007bff, #0056b3) !important;\n    color: #ffffff !important;\n    text-decoration: none !important;\n    border-radius: 50px !important;\n    font-weight: 600 !important;\n    font-size: 16px !important;\n    transition: all 0.3s ease !important;\n    box-shadow: 0 10px 25px rgba(0, 123, 255, 0.3);\n  }\n  .portfolio-btn:hover {\n    transform: translateY(-3px) !important;\n    box-shadow: 0 15px 35px rgba(0, 123, 255, 0.4) !important;\n    background: linear-gradient(135deg, #0056b3, #004085) !important;\n    color: #ffffff !important;\n  }\n  .portfolio-btn svg { width: 18px; height: 18px; transition: transform 0.3s ease; }\n  .portfolio-btn:hover svg { transform: translateX(4px); }\n\n  /* Мобильная версия */\n  @media (max-width: 768px) {\n    .portfolio-embed { m