"margin\":{\"top\":\"\",\"bottom\":\"2rem\"},\"size\":{\"unit\":\"px\",\"value\":\"12\"},\"weight\":\"600\",\"lineHeight\":{\"value\":\"1\",\"unit\":\"\"},\"transform\":\"uppercase\",\"letterSpacing\":{\"value\":\"1\",\"unit\":\"px\"}},\"border\":{\"top\":{\"color\":\"rgba(var(--kubio-color-1),1)\",\"style\":\"solid\",\"width\":{\"value\":\"2\",\"unit\":\"px\"},\"radius\":{\"right\":{\"value\":5,\"unit\":\"px\"},\"left\":{\"value\":5,\"unit\":\"px\"}}},\"bottom\":{\"color\":\"rgba(var(--kubio-color-1),1)\",\"style\":\"solid\",\"width\":{\"value\":\"2\",\"unit\":\"px\"},\"radius\":{\"right\":{\"value\":5,\"unit\":\"px\"},\"left\":{\"value\":5,\"unit\":\"px\"}}},\"right\":{\"color\":\"rgba(var(--kubio-color-1),1)\",\"style\":\"solid\",\"width\":{\"value\":\"2\",\"unit\":\"px\"}},\"left\":{\"color\":\"rgba(var(--kubio-color-1),1)\",\"style\":\"solid\",\"width\":{\"value\":\"2\",\"unit\":\"px\"}}},\"padding\":{\"top\":{\"unit\":\"px\",\"value\":\"12\"},\"bottom\":{\"unit\":\"px\",\"value\":\"12\"},\"left\":{\"unit\":\"px\",\"value\":\"24\"},\"right\":{\"unit\":\"px\",\"value\":\"24\"}},\"states\":{\"hover\":{\"background\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"border\":{\"top\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"right\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"bottom\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"},\"left\":{\"color\":\"rgba(var(--kubio-color-1-variant-4),1)\"}}}}},\"icon\":{\"size\":{\"unit\":\"px\",\"value\":\"12\"},\"margin\":{\"left\":{\"value\":10,\"unit\":\"px\"},\"right\":{\"value\":0,\"unit\":\"px\"}}}}},\"hash\":\"yg4JIvyDA\"},\"link\":{\"value\":\"https://ipkorotkov.online/contact/\",\"typeOpenLink\":\"sameWindow\",\"noFollow\":false,\"lightboxMedia\":\"\"},\"preserveSpace\":{\"text\":false},\"icon\":{\"name\":\"font-awesome/arrow-right\"}} -->\nСвязаться\n<!-- /wp:kubio/button -->\n<!-- /wp:kubio/buttongroup -->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n\n<!-- wp:html -->\n<style>\n  .portfolio-embed {\n    max-width: 1000px;\n    margin: 40px auto;\n    font-family: \'Manrope\', -apple-system, sans-serif;\n  }\n\n  .browser-mockup {\n    background: #0a0e1a;\n    border-radius: 16px;\n    overflow: hidden;\n    border: 1px solid rgba(127, 227, 201, 0.2);\n    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6), 0 0 40px rgba(127, 227, 201, 0.08);\n    transition: transform 0.4s ease, box-shadow 0.4s ease;\n  }\n  .browser-mockup:hover {\n    transform: translateY(-5px);\n    box-shadow: 0 35px 60px -15px rgba(0, 0, 0, 0.7), 0 0 60px rgba(127, 227, 201, 0.15);\n  }\n\n  .browser-header {\n    background: #0f1524;\n    padding: 14px 20px;\n    display: flex;\n    align-items: center;\n    gap: 15px;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n  }\n  .browser-dots { display: flex; gap: 8px; }\n  .browser-dots span { width: 12px; height: 12px; border-radius: 50%; }\n  .browser-dots span:nth-child(1) { background: #ff5f57; }\n  .browser-dots span:nth-child(2) { background: #ffbd2e; }\n  .browser-dots span:nth-child(3) { background: #28ca42; }\n\n  .browser-url {\n    flex: 1;\n    background: rgba(255, 255, 255, 0.06);\n    border-radius: 8px;\n    padding: 8px 16px;\n    font-size: 13px;\n    color: #8A94A8;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n  }\n  .browser-url svg { width: 14px; height: 14px; stroke: #7FE3C9; }\n\n  .browser-frame {\n    width: 100%;\n    height: 70vh;\n    min-height: 550px;\n    max-height: 800px;\n    border: none;\n    display: block;\n    background: #0a0e1a;\n  }\n\n  .portfolio-action { text-align: center; margin-top: 30px; }\n  .portfolio-btn {\n    display: inline-flex !important;\n    align-items: center;\n    justify-content: center;\n    gap: 10px;\n    padding: 16px 36px !important;\n    background: linear-gradient(135deg, #007bff, #0056b3) !important;\n    color: #ffffff !important;\n    text-decoration: none !important;\n    border-radius: 50px !important;\n    font-weight: 600 !important;\n    font-size: 16px !important;\n    transition: all 0.3s ease !important;\n    box-shadow: 0 10px 25px rgba(0, 123, 255, 0.3);\n  }\n  .portfolio-btn:hover {\n    transform: translateY(-3px) !important;\n    box-shadow: 0 15px 35px rgba(0, 123, 255, 0.4) !important;\n    background: linear-gradient(135deg, #0056b3, #004085) !important;\n    color: #ffffff !important;\n  }\n  .portfolio-btn svg { width: 18px; height: 18px; transition: transform 0.3s ease; }\n  .portfolio-btn:hover svg { transform: translateX(4px); }\n\n  /* Мобильная версия */\n  @media (max-width: 768px) {\n    .portfolio-embed { margin: 20px 0; }\n    .browser-mockup {\n      border-radius: 12px;\n      border: 1px solid rgba(127, 227, 201, 0.15);\n      box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4);\n    }\n    .browser-header { padding: 10px 14px; }\n    .browser-url { display: none; }\n    .browser-frame {\n      height: 85vh;\n      min-height: 600px;\n    }\n    .portfolio-btn {\n      width: 100% !important;\n      max-width: 100% !important;\n      border-radius: 12px !important;\n      padding: 18px 24px !important;\n    }\n  }\n\n  @media (max-width: 380px) {\n    .browser-frame {\n      height: 90vh;\n      min-height: 550px;\n    }\n  }\n</style>\n\n<div class=\"portfolio-embed\">\n  <div class=\"browser-mockup\">\n    <div class=\"browser-header\">\n      <div class=\"browser-dots\">\n        <span></span><span></span><span></span>\n      </div>\n      <div class=\"browser-url\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n          <rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\" ry=\"2\"/>\n          <path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/>\n        </svg>\n        ipkorotkov.online/lumiere/\n      </div>\n    </div>\n    \n    <iframe \n      class=\"browser-frame\" \n      src=\"https://ipkorotkov.online/lumiere/\" \n      loading=\"lazy\"\n      title=\"LUMIÈRE Dental Portfolio\"\n      allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\">\n    </iframe>\n  </div>\n\n  <div class=\"portfolio-action\">\n    <a href=\"https://ipkorotkov.online/lumiere/\" target=\"_blank\" class=\"portfolio-btn\">\n      Открыть работу на весь экран\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n        <path d=\"M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6\"/>\n        <polyline points=\"15 3 21 3 21 9\"/>\n        <line x1=\"10\" y1=\"14\" x2=\"21\" y2=\"3\"/>\n      </svg>\n    </a>\n  </div>\n</div>\n<!-- /wp:html -->\n<!-- /wp:kubio/section -->\n\n<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"LTlIa4_ic_\",\"style\":{\"descendants\":{\"outer\":{\"background\":{\"color\":\"rgba(var(--kubio-color-4),1)\"}}}},\"hash\":\"9uDNUlt5u\",\"props\":{\"width\":\"boxed\"}},\"attrs\":{\"name\":\"testimonials\"},\"anchor\":\"testimonials\"} -->\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"BcvHbU0JG\",\"hash\":\"pe-5EGgSdW\"},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/11/2026-11-15_04-04-04-1.png\",\"id\":547,\"sizeSlug\":\"full\"} /-->\n\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"t-KGh42MG\",\"hash\":\"yTSjpO8yP\",\"style\":{\"descendants\":{\"image\":{\"border\":{\"top\":{\"style\":\"none\"},\"right\":{\"style\":\"none\"},\"bottom\":{\"style\":\"none\"},\"left\":{\"style\":\"none\"}}},\"overlay\":{\"border\":{\"top\":{\"style\":\"none\"},\"right\":{\"style\":\"none\"},\"bottom\":{\"style\":\"none\"},\"left\":{\"style\":\"none\"}}}}}},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/11/2026-11-15_04-04-30-1.png\",\"id\":548,\"sizeSlug\":\"full\"} /-->\n\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"-iRq7RQBS\",\"hash\":\"7LG-PN8-v\"},\"link\":{\"typeOpenLink\":\"sameWindow\",\"lightboxMedia\":\"\",\"value\":\"\"},\"url\":\"https://ipkorotkov.online/wp-content/uploads/2026/11/2026-11-15_04-05-17-1.png\",\"id\":549,\"sizeSlug\":\"full\"} /-->\n\n