idth:100%;max-width:none;margin:0;padding:0 0 1px;position:relative;isolation:isolate;overflow:hidden}\n.pp-github *{box-sizing:border-box}\n.pp-github a{color:var(--pp-cyan);text-decoration:none}\n.pp-github a:hover{color:var(--pp-lime);text-decoration:underline;text-underline-offset:4px}\n.pp-github .pp-wrap{width:100%;max-width:1360px;margin:0 auto;padding:0 34px}\n.pp-github .pp-hero{position:relative;padding:64px 0 58px;background:radial-gradient(ellipse at 12% 10%,rgba(182,242,74,.13),transparent 35%),radial-gradient(ellipse at 90% 18%,rgba(109,155,255,.18),transparent 38%),linear-gradient(145deg,#0c1120,#080b14 65%);border-bottom:1px solid var(--pp-line)}\n.pp-github .pp-hero:before{content:\"\";position:absolute;inset:0;pointer-events:none;opacity:.42;background-image:linear-gradient(rgba(109,155,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(109,155,255,.07) 1px,transparent 1px);background-size:48px 48px;mask-image:radial-gradient(ellipse at 50% 20%,#000 15%,transparent 78%)}\n.pp-github .pp-hero-in{position:relative;z-index:1;max-width:1180px}\n.pp-github .pp-eyebrow{display:inline-flex;align-items:center;gap:10px;color:var(--pp-lime);font:700 11px/1.4 \'JetBrains Mono\',monospace;letter-spacing:.16em;text-transform:uppercase;margin:0 0 18px}\n.pp-github .pp-eyebrow:before{content:\"\";width:25px;height:2px;background:var(--pp-g);display:inline-block}\n.pp-github .pp-gradient{background:var(--pp-g);-webkit-background-clip:text;background-clip:text;color:transparent}\n.pp-github .pp-intro{font-size:clamp(17px,1.65vw,21px);color:var(--pp-mut);max-width:1080px;margin:0 0 27px}\n.pp-github .pp-actions{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 25px}\n.pp-github .pp-btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:14px 22px;border-radius:13px;background:var(--pp-g);color:#08130a!important;font-weight:900;box-shadow:0 10px 30px rgba(109,155,255,.22);transition:.2s}\n.pp-github .pp-btn:hover{transform:translateY(-3px);text-decoration:none;box-shadow:0 14px 36px rgba(109,155,255,.34)}\n.pp-github .pp-btn-ghost{background:transparent;color:var(--pp-tx)!important;border:1px solid var(--pp-line2);box-shadow:none}\n.pp-github .pp-btn-ghost:hover{border-color:var(--pp-lime);color:var(--pp-lime)!important}\n.pp-github .pp-chips{display:flex;gap:8px;flex-wrap:wrap}\n.pp-github .pp-chip{font:600 11px \'JetBrains Mono\',monospace;color:var(--pp-mut);padding:7px 11px;border:1px solid var(--pp-line2);border-radius:99px;background:rgba(18,26,46,.7)}\n.pp-github .pp-chip strong{color:var(--pp-lime);font-weight:700}\n.pp-github .pp-section{padding:58px 0;border-bottom:1px solid var(--pp-line);position:relative}\n.pp-github .pp-section:nth-child(odd){background:linear-gradient(180deg,rgba(18,26,46,.35),rgba(8,11,20,0))}\n.pp-github .pp-label{color:var(--pp-lime);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.15em;text-transform:uppercase;margin:0 0 12px}\n.pp-github h2{font-family:\'Onest\',Arial,sans-serif;font-size:clamp(25px,3vw,37px);font-weight:900;letter-spacing:-.025em;line-height:1.15;color:var(--pp-tx);margin:0 0 16px}\n.pp-github h3{font-family:\'Onest\',Arial,sans-serif;font-size:19px;font-weight:800;letter-spacing:-.02em;line-height:1.25;color:var(--pp-tx);margin:0 0 9px}\n.pp-github .pp-lead{color:var(--pp-mut);font-size:16px;max-width:1060px;margin:0 0 27px}\n.pp-github .pp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}\n.pp-github .pp-card{position:relative;overflow:hidden;background:linear-gradient(150deg,var(--pp-sur),#0d1425);border:1px solid var(--pp-line);border-radius:17px;padding:25px 24px;min-height:190px;transition:.2s}\n.pp-github .pp-card:hover{transform:translateY(-3px);border-color:var(--pp-line2);box-shadow:0 18px 45px rgba(0,0,0,.3)}\n.pp-github .pp-card:before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--pp-accent,var(--pp-cyan))}\n.pp-github .pp-card p,.pp-github .pp-step p{color:var(--pp-mut);font-size:14px;margin:0}\n.pp-github .pp-num{font:800 12px \'JetBrains Mono\',monospace;color:var(--pp-accent,var(--pp-lime));margin:0 0 14px;letter-spacing:.12em}\n.pp-github .pp-card .pp-icon{width:41px;height:41px;border-radius:12px;display:grid;place-items:center;background:rgba(109,155,255,.12);color:var(--pp-accent,var(--pp-cyan));font-size:21px;margin:0 0 14px}\n.pp-github .pp-data{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px 16px;margin:23px 0 0;padding:0;list-style:none}\n.pp-github .pp-data li{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:11px;padding:13px 15px 13px 40px;position:relative;color:var(--pp-tx);font-size:14px}\n.pp-github .pp-data li:before{content:\"✓\";position:absolute;left:15px;top:12px;color:var(--pp-lime);font-weight:900}\n.pp-github .pp-price-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:23px 0}\n.pp-github .pp-price{padding:24px;border:1px solid var(--pp-line2);border-radius:16px;background:linear-gradient(145deg,#111b30,#0b1120)}\n.pp-github .pp-price small{display:block;color:var(--pp-mut);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.12em;text-transform:uppercase;margin-bottom:9px}\n.pp-github .pp-price strong{display:block;color:var(--pp-lime);font:900 clamp(25px,3vw,36px)/1.2 \'Onest\',Arial,sans-serif}\n.pp-github .pp-price p{font-size:13px;color:var(--pp-mut);margin:9px 0 0}\n.pp-github .pp-factors{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;counter-reset:factor}\n.pp-github .pp-factor{counter-increment:factor;padding:18px 19px;border:1px solid var(--pp-line);border-radius:13px;background:rgba(18,26,46,.65)}\n.pp-github .pp-factor:before{content:\"0\" counter(factor);display:block;color:var(--pp-cyan);font:800 12px \'JetBrains Mono\',monospace;margin-bottom:9px}\n.pp-github .pp-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;counter-reset:ppstep}\n.pp-github .pp-step{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:15px;padding:21px;counter-increment:ppstep}\n.pp-github .pp-step:before{content:\"0\" counter(ppstep);display:block;font:900 25px \'Onest\',sans-serif;background:var(--pp-g);-webkit-background-clip:text;background-clip:text;color:transparent;margin:0 0 12px}\n.pp-github .pp-example{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:22px}\n.pp-github .pp-example article{padding:20px;border:1px solid var(--pp-line);border-radius:14px;background:var(--pp-sur)}\n.pp-github .pp-example strong{display:block;color:var(--pp-lime);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.1em;margin-bottom:9px}\n.pp-github .pp-example p{color:var(--pp-mut);font-size:14px;margin:0}\n.pp-github .pp-note{display:flex;gap:13px;align-items:flex-start;background:rgba(255,194,71,.07);border:1px solid rgba(255,194,71,.35);border-radius:13px;padding:16px 18px;margin:22px 0 0;color:var(--pp-mut);font-size:13.5px}\n.pp-github .pp-note strong{color:#ffc247}\n.pp-github .pp-faq{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.pp-github .pp-faq details{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:13px;padding:17px 19px}\n.pp-github .pp-faq summary{cursor:pointer;font:800 15px/1.4 \'Onest\',Arial,sans-serif;color:var(--pp-cyan)}\n.pp-github .pp-faq details p{font-size:14px;color:var(--pp-mut);margin:12px 0 0}\n.pp-github .pp-related{padding:21px 23px;border:1px solid var(--pp-line);border-radius:14px;background:rgba(18,26,46,.6);margin-top:23px;color:var(--pp-mut)}\n.pp-github .pp-related p{margin:0 0 10px}.pp-github .pp-related p:last-child{margin-bottom:0}\n.pp-github .pp-final{padding:48px 28px;text-align:center;border:1px solid var(--pp-line2);border-radius:19px;background:radial-gradient(ellipse at 20% 0%,rgba(182,242,74,.12),transparent 40%),linear-gradient(140deg,#0c1120,#121a2e 55%,#1a1638);box-shadow:0 22px 65px rgba(0,0,0,.24)}\n.pp-github .pp-final h2{font-size:clamp(27px,3.6vw,42px)}\n.pp-github .pp-final p{max-width:900px;margin:0 auto 22px;color:var(--pp-mut)}\n.pp-github .pp-contact{display:flex;justify-content:center;gap:17px;flex-wrap:wrap;margin-top:19px;font:600 13px \'JetBrains Mono\',monospace;color:var(--pp-mut)}\n.pp-github .pp-contact a{color:var(--pp-tx);border-bottom:1px dashed var(--pp-cyan)}\n@media(max-width:900px){.pp-github .pp-wrap{padding:0 22px}.pp-github .pp-steps{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:650px){.pp-github .pp-wrap{padding:0 16px}.pp-github .pp-hero{padding:42px 0 38px}.pp-github .pp-section{padding:42px 0}.pp-github .pp-grid,.pp-github .pp-steps,.pp-github .pp-faq,.pp-github .pp-price-grid,.pp-github .pp-factors,.pp-github .pp-example{grid-template-columns:1fr}.pp-github .pp-data{grid-template-columns:1fr}.pp-github .pp-card{min-height:0}.pp-github .pp-final{padding:35px 18px}}\n@media(prefers-reduced-motion:reduce){.pp-github *{transition:none!important}}\n</style>\n\n<div class=\"pp-github\">\n<section class=\"pp-hero\">\n <div class=\"pp-wrap\"><div class=\"pp-hero-in\">\n  <div class=\"pp-eyebrow\">Сбор данных · сравнение · автоматизация</div>\n  <p class=\"pp-intro\">Парсер цен автоматически собирает стоимость товаров с выбранных сайтов, чтобы сравнивать предложения без постоянной ручной проверки. Разработаю сбор данных под ваши источники и подготовлю результат в Excel или CSV либо в формате для дальнейшей обработки.</p>\n  <div class=\"pp-actions\"><a class=\"pp-btn\" href=\"tel:+79641519362\">Обсудить задачу <span>↗</span></a><a class=\"pp-btn pp-btn-ghost\" href=\"https://t.me/+79641519362\">Написать в Telegram</a></div>\n  <div class=\"pp-chips\"><span class=\"pp-chip\"><strong>01</strong> Сбор цен</span><span class=\"pp-chip\"><strong>02</strong> Сопоставление товаров</span><span class=\"pp-chip\"><strong>03</strong> Excel / CSV</span><span class=\"pp-chip\">Удалённая работа по России</span></div>\n </div></div>\n</section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Результат разработки</div><h2>Что получите после разработки <span class=\"pp-gradient\">парсера цен</span></h2>\n <p class=\"pp-lead\">Состав результата фиксируем до начала работ. Это не просто таблица с набором случайных значений: данные собираются по согласованным правилам, очищаются и приводятся к формату, с которым можно работать дальше — вручную, в отчёте или в другой программе.</p>\n <div class=\"pp-grid\">\n  <article class=\"pp-card\" style=\"--pp-accent:#b6f24a\"><div class=\"pp-num\">01 / ИНСТРУМЕНТ</div><div class=\"pp-icon\">⌘</div><h3>Рабочий сборщик</h3><p>Программа или скрипт, настроенный на согласованные сайты, категории или список товарных страниц. Способ запуска и требования к окружению описываются при передаче.</p></article>\n  <article class=\"pp-card\" style=\"--pp-accent:#2dd4f7\"><div class=\"pp-num\">02 / ВЫГРУЗКА</div><div class=\"pp-icon\">▤</div><h3>Таблица с данными</h3><p>Файл Excel или CSV с названием товара, ссылкой, ценой, артикулом, наличием и другими согласованными полями. Лишние и пустые значения можно отфильтровать.</p></article>\n  <article class=\"pp-card\" style=\"--pp-accent:#b18cff\"><div class=\"pp-num\">03 / ПЕРЕДАЧА</div><div class=\"pp-icon\">✓</div><h3>Проверка и пояснения</h3><p>Тестовая выгрузка для сверки, описание основных настроек и рекомендации по запуску. Если требуется регулярный сбор, отдельно согласуем порядок обновления.</p></article>\n </div>\n <ul class=\"pp-data\"><li>Название и URL товара</li><li>Текущая и прежняя цена, если доступны</li><li>Артикул или код позиции</li><li>Характеристики и варианты товара</li><li>Наличие или статус предложения</li><li>Магазин или название источника</li><li>Дата и время получения данных</li><li>Поля для сопоставления аналогов</li></ul>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Бюджет и сроки</div><h2>Цена и срок разработки <span class=\"pp-gradient\">парсера цен</span></h2>\n <p class=\"pp-lead\">Для простой задачи с одним доступным источником ориентир начинается от 5 000 ₽, срок — от 3 рабочих дней. Это предварительная оценка, а не фиксированная цена для любого сайта: после проверки страниц и требований я уточню объём работ и согласую итоговые условия.</p>\n <div class=\"pp-price-grid\">\n  <div class=\"pp-price\"><small>Стоимость</small><strong>от 5 000 ₽</strong><p>Начальная оценка простой выгрузки; окончательная сумма зависит от состава задачи.</p></div>\n  <div class=\"pp-price\"><small>Срок</small><strong>от 3 рабочих дней</strong><p>Отсчёт после согласования источников, полей и условий доступа к данным.</p></div>\n </div>\n <p class=\"pp-lead\">На стоимость влияют три основных фактора:</p>\n <div class=\"pp-factors\">\n  <div class=\"pp-factor\"><h3>Источники и их структура</h3><p>Количество сайтов, тип страниц, различия в карточках и наличие технических ограничений.</p></div>\n  <div class=\"pp-factor\"><h3>Объём и состав каталога</h3><p>Число позиций, набор собираемых полей, варианты товаров и правила очистки данных.</p></div>\n  <div class=\"pp-factor\"><h3>Логика обновления</h3><p>Разовая выгрузка или расписание, история изменений, сопоставление одинаковых товаров и формат отчёта.</p></div>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Рабочий процесс</div><h2>Как делаю: четыре этапа <span class=\"pp-gradient\">от проверки до передачи</span></h2>\n <p class=\"pp-lead\">До разработки определяем, какие сведения нужны и как вы будете ими пользоваться. Это помогает не собирать лишние данные и не усложнять инструмент без необходимости.</p>\n <div class=\"pp-steps\">\n  <article class=\"pp-step\"><h3>Разбираю задачу</h3><p>Получаю адреса сайтов или примеры карточек, список нужных полей и желаемый формат результата. Уточняю, какие товары нужно сопоставлять.</p></article>\n  <article class=\"pp-step\"><h3>Проверяю источники</h3><p>Изучаю структуру страниц, доступность информации и частоту изменений. На этом этапе выявляются ограничения, которые могут повлиять на сроки и состав решения.</p></article>\n  <article class=\"pp-step\"><h3>Разрабатываю и тестирую</h3><p>Настраиваю получение информации, обработку значений и формирование выгрузки. Проверяю результат на согласованных примерах, исправляю ошибки обработки.</p></article>\n  <article class=\"pp-step\"><h3>Передаю результат</h3><p>Подготавливаю файлы и инструкцию, показываю тестовую таблицу. При необходимости отдельно обсуждаем запуск по расписанию и дальнейшее сопровождение.</p></article>\n </div>\n <div class=\"pp-note\"><div style=\"font-size:19px;line-height:1\">!</div><div><strong>Условия сбора:</strong> работаю с информацией, доступной на выбранных страницах, с учётом правил и ограничений источника. Обход авторизации, CAPTCHA и технических защит не включается в стандартную задачу.</div></div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Пример постановки задачи</div><h2>Как может выглядеть <span class=\"pp-gradient\">результат</span></h2>\n <p class=\"pp-lead\">Ниже — условный пример для иллюстрации процесса, а не описание выполненного проекта или отзыв заказчика.</p>\n <div class=\"pp-example\">\n  <article><strong>БЫЛО</strong><p>Сотруднику приходится открывать страницы магазинов по очереди, вручную переписывать цены и затем сводить значения в одну таблицу. При повторной проверке трудно заметить, что изменилось.</p></article>\n  <article><strong>СДЕЛАЛ</strong><p>Для выбранных страниц настраивается сбор названия товара, ссылки, цены и даты проверки. Значения приводятся к единому формату и выгружаются в Excel или CSV.</p></article>\n  <article><strong>СТАЛО</strong><p>Вместо разрозненных записей появляется общая таблица, которую можно сортировать, фильтровать и использовать для сравнения предложений. Фактическая автоматизация зависит от доступности источников.</p></article>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Частые вопросы</div><h2>Что важно знать <span class=\"pp-gradient\">перед заказом</span></h2>\n <div class=\"pp-faq\">\n  <details><summary>Можно собирать цены сразу с нескольких сайтов?</summary><p>Да, если страницы и данные доступны для обработки. Каждый источник проверяется отдельно: у сайтов могут различаться структура карточек, названия полей и правила отображения цены. Количество источников учитывается в оценке стоимости и срока.</p></details>\n  <details><summary>Какие поля можно включить в выгрузку?</summary><p>Обычно это название товара, ссылка, цена, артикул, наличие, характеристики, продавец и дата проверки. Точный набор зависит от информации на странице. Перед разработкой согласуем список, чтобы таблица содержала нужные данные, а не лишние колонки.</p></details>\n  <details><summary>В каком формате я получу результат?</summary><p>Для работы с таблицами подойдут Excel или CSV. Если данные нужно передавать в другую программу, можно обсудить JSON или иной согласованный формат. Способ передачи выбирается с учётом того, где и как вы планируете использовать собранную информацию.</p></details>\n  <details><summary>Можно настроить регулярное обновление цен?</summary><p>Можно предусмотреть запуск по расписанию, если это допускают источник и выбранная инфраструктура. Частота проверок согласуется заранее: слишком частые запросы могут создавать нагрузку и приводить к ограничениям со стороны сайта.</p></details>\n  <details><summary>Что нужно прислать для расчёта стоимости?</summary><p>Достаточно отправить ссылки на несколько типовых страниц, список нужных полей и пример того, как должна выглядеть итоговая таблица. По этим материалам можно проверить структуру источников, определить возможные ограничения и назвать более точную цену и срок.</p></details>\n </div>\n <div class=\"pp-related\">\n  <p>Для постоянного отслеживания изменений пригодится услуга <a href=\"/services/monitoring-cen-konkurentov/\">мониторинг цен конкурентов</a>. Когда нужно свести предложения в общий отчёт, можно дополнить сбор <a href=\"/services/tablica-sravneniya-cen-konkurentov/\">таблицей сравнения цен конкурентов</a>. Если цены размещены в кабинетах и каталогах поставщиков, отдельно рассмотрим <a href=\"/services/parsing-cen-postavshchikov/\">парсинг цен поставщиков</a>.</p>\n  <p>Все направления разработки собраны на странице <a href=\"/services/\">«Услуги»</a>.</p>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-final\"><div class=\"pp-label\">Обсудим задачу</div><h2>Нужен <span class=\"pp-gradient\">парсер цен</span>?</h2><p>Пришлите ссылки на сайты и напишите, какие товары и параметры требуется собирать. Я проверю источники, предложу состав выгрузки и обозначу стоимость и срок до начала разработки.</p><div class=\"pp-actions\" style=\"justify-content:center\"><a class=\"pp-btn\" href=\"tel:+79641519362\">Позвонить: +7 (964) 151-93-62 ↗</a><a class=\"pp-btn pp-btn-ghost\" href=\"https://t.me/+79641519362\">Написать в Telegram</a></div><div class=\"pp-contact\"><span>Телефон: <a href=\"tel:+79641519362\">+7 (964) 151-93-62</a></span><span>Email: <a href=\"mailto:tochka_rosta24@list.ru\">tochka_rosta24@list.ru</a></span></div></div>\n</div></section>\n</div>\n\n<script type=\"application/ld+json\">\n{\n \"@context\":\"https://schema.org\",\n \"@graph\":[\n  {\n   \"@type\":\"Service\",\n   \"@id\":\"https://ipkorotkov.online/services/parser-cen/#service\",\n   \"name\":\"Разработка парсера цен\",\n   \"serviceType\":\"Сбор и мониторинг цен товаров с сайтов\",\n   \"url\":\"https://ipkorotkov.online/services/parser-cen/\",\n   \"description\":\"Разработка парсера для сбора цен товаров с выбранных сайтов с подготовкой выгрузки Excel или CSV.\",\n   \"provider\":{\"@type\":\"Person\",\"name\":\"Константин Коротков\"},\n   \"areaServed\":{\"@type\":\"Country\",\"name\":\"Россия\"},\n   \"offers\":{\"@type\":\"Offer\",\"price\":\"5000\",\"priceCurrency\":\"RUB\",\"description\":\"Начальная ориентировочная стоимость простой задачи\"}\n  },\n  {\n   \"@type\":\"FAQPage\",\n   \"@id\":\"https://ipkorotkov.online/services/parser-cen/#faq\",\n   \"mainEntity\":[\n    {\"@type\":\"Question\",\"name\":\"Можно собирать цены сразу с нескольких сайтов?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Да, если страницы и данные доступны для обработки. Каждый источник проверяется отдельно; количество источников учитывается в оценке стоимости и срока.\"}},\n    {\"@type\":\"Question\",\"name\":\"Какие поля можно включить в выгрузку?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Обычно это название товара, ссылка, цена, артикул, наличие, характеристики, продавец и дата проверки. Точный набор зависит от информации на странице.\"}},\n    {\"@type\":\"Question\",\"name\":\"В каком формате я получу результат?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Для таблиц подойдут Excel или CSV. Для передачи в другую программу можно обсудить JSON или иной согласованный формат.\"}},\n    {\"@type\":\"Question\",\"name\":\"Можно настроить регулярное обновление цен?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Можно предусмотреть запуск по расписанию, если это допускают источник и выбранная инфраструктура. Частота проверок согласуется заранее.\"}},\n    {\"@type\":\"Question\",\"name\":\"Что нужно прислать для расчёта стоимости?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Нужно отправить ссылки на несколько типовых страниц, список нужных полей и пример итоговой таблицы. По этим материалам проверяются источники и уточняются цена и срок.\"}}\n   ]\n  }\n ]\n}\n</script>\n<!-- /wp:html -->','Парсер цен','Разработка парсера цен для автоматического сбора стоимости товаров, мониторинга цен конкурентов и сравнения предложений интернет-магазинов.','inherit','closed','closed','','575-revision-v1','','','2026-11-23 06:52:29','2026-11-23 06:52:29','',575,'https://ipkorotkov.online/?p=624',0,'revision','',0),(625,1,'2026-11-23 06:53:32','2026-11-23 06:53:32','<!-- wp:html -->\n<style>\n.pp-github{--pp-ink:#080b14;--pp-ink2:#0c1120;--pp-sur:#121a2e;--pp-sur2:#18233c;--pp-line:#243352;--pp-line2:#33456b;--pp-tx:#eaf0fb;--pp-mut:#a9b8d5;--pp-lime:#b6f24a;--pp-cyan:#2dd4f7;--pp-blue:#6d9bff;--pp-violet:#b18cff;--pp-g:linear-gradient(100deg,var(--pp-lime),var(--pp-cyan) 42%,var(--pp-blue) 72%,var(--pp-violet));background:var(--pp-ink);color:var(--pp-tx);font:16px/1.72 \'Manrope\',Arial,sans-serif;width:min(96vw,1480px);max-width:1480px;margin:0;padding:0 0 1px;position:relative;left:50%;transform:translateX(-50%);isolation:isolate;overflow:hidden}\n.pp-github *{box-sizing:border-box}\n.pp-github a{color:var(--pp-cyan);text-decoration:none}\n.pp-github a:hover{color:var(--pp-lime);text-decoration:underline;text-underline-offset:4px}\n.pp-github .pp-wrap{width:100%;max-width:1360px;margin:0 auto;padding:0 34px}\n.pp-github .pp-hero{position:relative;padding:64px 0 58px;background:radial-gradient(ellipse at 12% 10%,rgba(182,242,74,.13),transparent 35%),radial-gradient(ellipse at 90% 18%,rgba(109,155,255,.18),transparent 38%),linear-gradient(145deg,#0c1120,#080b14 65%);border-bottom:1px solid var(--pp-line)}\n.pp-github .pp-hero:before{content:\"\";position:absolute;inset:0;pointer-events:none;opacity:.42;background-image:linear-gradient(rgba(109,155,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(109,155,255,.07) 1px,transparent 1px);background-size:48px 48px;mask-image:radial-gradient(ellipse at 50% 20%,#000 15%,transparent 78%)}\n.pp-github .pp-hero-in{position:relative;z-index:1;max-width:1180px}\n.pp-github .pp-eyebrow{display:inline-flex;align-items:center;gap:10px;color:var(--pp-lime);font:700 11px/1.4 \'JetBrains Mono\',monospace;letter-spacing:.16em;text-transform:uppercase;margin:0 0 18px}\n.pp-github .pp-eyebrow:before{content:\"\";width:25px;height:2px;background:var(--pp-g);display:inline-block}\n.pp-github .pp-gradient{background:var(--pp-g);-webkit-background-clip:text;background-clip:text;color:transparent}\n.pp-github .pp-intro{font-size:clamp(17px,1.65vw,21px);color:var(--pp-mut);max-width:1080px;margin:0 0 27px}\n.pp-github .pp-actions{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 25px}\n.pp-github .pp-btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:14px 22px;border-radius:13px;background:var(--pp-g);color:#08130a!important;font-weight:900;box-shadow:0 10px 30px rgba(109,155,255,.22);transition:.2s}\n.pp-github .pp-btn:hover{transform:translateY(-3px);text-decoration:none;box-shadow:0 14px 36px rgba(109,155,255,.34)}\n.pp-github .pp-btn-ghost{background:transparent;color:var(--pp-tx)!important;border:1px solid var(--pp-line2);box-shadow:none}\n.pp-github .pp-btn-ghost:hover{border-color:var(--pp-lime);color:var(--pp-lime)!important}\n.pp-github .pp-chips{display:flex;gap:8px;flex-wrap:wrap}\n.pp-github .pp-chip{font:600 11px \'JetBrains Mono\',monospace;color:var(--pp-mut);padding:7px 11px;border:1px solid var(--pp-line2);border-radius:99px;background:rgba(18,26,46,.7)}\n.pp-github .pp-chip strong{color:var(--pp-lime);font-weight:700}\n.pp-github .pp-section{padding:58px 0;border-bottom:1px solid var(--pp-line);position:relative}\n.pp-github .pp-section:nth-child(odd){background:linear-gradient(180deg,rgba(18,26,46,.35),rgba(8,11,20,0))}\n.pp-github .pp-label{color:var(--pp-lime);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.15em;text-transform:uppercase;margin:0 0 12px}\n.pp-github h2{font-family:\'Onest\',Arial,sans-serif;font-size:clamp(25px,3vw,37px);font-weight:900;letter-spacing:-.025em;line-height:1.15;color:var(--pp-tx);margin:0 0 16px}\n.pp-github h3{font-family:\'Onest\',Arial,sans-serif;font-size:19px;font-weight:800;letter-spacing:-.02em;line-height:1.25;color:var(--pp-tx);margin:0 0 9px}\n.pp-github .pp-lead{color:var(--pp-mut);font-size:16px;max-width:1060px;margin:0 0 27px}\n.pp-github .pp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}\n.pp-github .pp-card{position:relative;overflow:hidden;background:linear-gradient(150deg,var(--pp-sur),#0d1425);border:1px solid var(--pp-line);border-radius:17px;padding:25px 24px;min-height:190px;transition:.2s}\n.pp-github .pp-card:hover{transform:translateY(-3px);border-color:var(--pp-line2);box-shadow:0 18px 45px rgba(0,0,0,.3)}\n.pp-github .pp-card:before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--pp-accent,var(--pp-cyan))}\n.pp-github .pp-card p,.pp-github .pp-step p{color:var(--pp-mut);font-size:14px;margin:0}\n.pp-github .pp-num{font:800 12px \'JetBrains Mono\',monospace;color:var(--pp-accent,var(--pp-lime));margin:0 0 14px;letter-spacing:.12em}\n.pp-github .pp-card .pp-icon{width:41px;height:41px;border-radius:12px;display:grid;place-items:center;background:rgba(109,155,255,.12);color:var(--pp-accent,var(--pp-cyan));font-size:21px;margin:0 0 14px}\n.pp-github .pp-data{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px 16px;margin:23px 0 0;padding:0;list-style:none}\n.pp-github .pp-data li{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:11px;padding:13px 15px 13px 40px;position:relative;color:var(--pp-tx);font-size:14px}\n.pp-github .pp-data li:before{content:\"✓\";position:absolute;left:15px;top:12px;color:var(--pp-lime);font-weight:900}\n.pp-github .pp-price-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:23px 0}\n.pp-github .pp-price{padding:24px;border:1px solid var(--pp-line2);border-radius:16px;background:linear-gradient(145deg,#111b30,#0b1120)}\n.pp-github .pp-price small{display:block;color:var(--pp-mut);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.12em;text-transform:uppercase;margin-bottom:9px}\n.pp-github .pp-price strong{display:block;color:var(--pp-lime);font:900 clamp(25px,3vw,36px)/1.2 \'Onest\',Arial,sans-serif}\n.pp-github .pp-price p{font-size:13px;color:var(--pp-mut);margin:9px 0 0}\n.pp-github .pp-factors{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;counter-reset:factor}\n.pp-github .pp-factor{counter-increment:factor;padding:18px 19px;border:1px solid var(--pp-line);border-radius:13px;background:rgba(18,26,46,.65)}\n.pp-github .pp-factor:before{content:\"0\" counter(factor);display:block;color:var(--pp-cyan);font:800 12px \'JetBrains Mono\',monospace;margin-bottom:9px}\n.pp-github .pp-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;counter-reset:ppstep}\n.pp-github .pp-step{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:15px;padding:21px;counter-increment:ppstep}\n.pp-github .pp-step:before{content:\"0\" counter(ppstep);display:block;font:900 25px \'Onest\',sans-serif;background:var(--pp-g);-webkit-background-clip:text;background-clip:text;color:transparent;margin:0 0 12px}\n.pp-github .pp-example{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:22px}\n.pp-github .pp-example article{padding:20px;border:1px solid var(--pp-line);border-radius:14px;background:var(--pp-sur)}\n.pp-github .pp-example strong{display:block;color:var(--pp-lime);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.1em;margin-bottom:9px}\n.pp-github .pp-example p{color:var(--pp-mut);font-size:14px;margin:0}\n.pp-github .pp-note{display:flex;gap:13px;align-items:flex-start;background:rgba(255,194,71,.07);border:1px solid rgba(255,194,71,.35);border-radius:13px;padding:16px 18px;margin:22px 0 0;color:var(--pp-mut);font-size:13.5px}\n.pp-github .pp-note strong{color:#ffc247}\n.pp-github .pp-faq{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.pp-github .pp-faq details{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:13px;padding:17px 19px}\n.pp-github .pp-faq summary{cursor:pointer;font:800 15px/1.4 \'Onest\',Arial,sans-serif;color:var(--pp-cyan)}\n.pp-github .pp-faq details p{font-size:14px;color:var(--pp-mut);margin:12px 0 0}\n.pp-github .pp-related{padding:21px 23px;border:1px solid var(--pp-line);border-radius:14px;background:rgba(18,26,46,.6);margin-top:23px;color:var(--pp-mut)}\n.pp-github .pp-related p{margin:0 0 10px}.pp-github .pp-related p:last-child{margin-bottom:0}\n.pp-github .pp-final{padding:48px 28px;text-align:center;border:1px solid var(--pp-line2);border-radius:19px;background:radial-gradient(ellipse at 20% 0%,rgba(182,242,74,.12),transparent 40%),linear-gradient(140deg,#0c1120,#121a2e 55%,#1a1638);box-shadow:0 22px 65px rgba(0,0,0,.24)}\n.pp-github .pp-final h2{font-size:clamp(27px,3.6vw,42px)}\n.pp-github .pp-final p{max-width:900px;margin:0 auto 22px;color:var(--pp-mut)}\n.pp-github .pp-contact{display:flex;justify-content:center;gap:17px;flex-wrap:wrap;margin-top:19px;font:600 13px \'JetBrains Mono\',monospace;color:var(--pp-mut)}\n.pp-github .pp-contact a{color:var(--pp-tx);border-bottom:1px dashed var(--pp-cyan)}\n@media(max-width:900px){.pp-github .pp-wrap{padding:0 22px}.pp-github .pp-steps{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:650px){.pp-github .pp-wrap{padding:0 16px}.pp-github .pp-hero{padding:42px 0 38px}.pp-github .pp-section{padding:42px 0}.pp-github .pp-grid,.pp-github .pp-steps,.pp-github .pp-faq,.pp-github .pp-price-grid,.pp-github .pp-factors,.pp-github .pp-example{grid-template-columns:1fr}.pp-github .pp-data{grid-template-columns:1fr}.pp-github .pp-card{min-height:0}.pp-github .pp-final{padding:35px 18px}}\n@media(prefers-reduced-motion:reduce){.pp-github *{transition:none!important}}\n</style>\n\n<div class=\"pp-github\">\n<section class=\"pp-hero\">\n <div class=\"pp-wrap\"><div class=\"pp-hero-in\">\n  <div class=\"pp-eyebrow\">Сбор данных · сравнение · автоматизация</div>\n  <p class=\"pp-intro\">Парсер цен автоматически собирает стоимость товаров с выбранных сайтов, чтобы сравнивать предложения без постоянной ручной проверки. Разработаю сбор данных под ваши источники и подготовлю результат в Excel или CSV либо в формате для дальнейшей обработки.</p>\n  <div class=\"pp-actions\"><a class=\"pp-btn\" href=\"tel:+79641519362\">Обсудить задачу <span>↗</span></a><a class=\"pp-btn pp-btn-ghost\" href=\"https://t.me/+79641519362\">Написать в Telegram</a></div>\n  <div class=\"pp-chips\"><span class=\"pp-chip\"><strong>01</strong> Сбор цен</span><span class=\"pp-chip\"><strong>02</strong> Сопоставление товаров</span><span class=\"pp-chip\"><strong>03</strong> Excel / CSV</span><span class=\"pp-chip\">Удалённая работа по России</span></div>\n </div></div>\n</section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Результат разработки</div><h2>Что получите после разработки <span class=\"pp-gradient\">парсера цен</span></h2>\n <p class=\"pp-lead\">До начала работ согласуем поля и правила обработки. Итоговые данные будут готовы для анализа в таблице или передачи в другую программу.</p>\n <div class=\"pp-grid\">\n  <article class=\"pp-card\" style=\"--pp-accent:#b6f24a\"><div class=\"pp-num\">01 / ИНСТРУМЕНТ</div><div class=\"pp-icon\">⌘</div><h3>Рабочий сборщик</h3><p>Программа или скрипт, настроенный на согласованные сайты, категории или список товарных страниц. Способ запуска и требования к окружению описываются при передаче.</p></article>\n  <article class=\"pp-card\" style=\"--pp-accent:#2dd4f7\"><div class=\"pp-num\">02 / ВЫГРУЗКА</div><div class=\"pp-icon\">▤</div><h3>Таблица с данными</h3><p>Файл Excel или CSV с названием товара, ссылкой, ценой, артикулом, наличием и другими согласованными полями. Лишние и пустые значения можно отфильтровать.</p></article>\n  <article class=\"pp-card\" style=\"--pp-accent:#b18cff\"><div class=\"pp-num\">03 / ПЕРЕДАЧА</div><div class=\"pp-icon\">✓</div><h3>Проверка и пояснения</h3><p>Тестовая выгрузка для сверки, описание основных настроек и рекомендации по запуску. Если требуется регулярный сбор, отдельно согласуем порядок обновления.</p></article>\n </div>\n <ul class=\"pp-data\"><li>Название и URL товара</li><li>Текущая и прежняя цена, если доступны</li><li>Артикул или код позиции</li><li>Характеристики и варианты товара</li><li>Наличие или статус предложения</li><li>Магазин или название источника</li><li>Дата и время получения данных</li><li>Поля для сопоставления аналогов</li></ul>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Бюджет и сроки</div><h2>Цена и срок разработки <span class=\"pp-gradient\">парсера цен</span></h2>\n <p class=\"pp-lead\">Для простой задачи с одним доступным источником ориентир — от 5 000 ₽ и от 3 рабочих дней. Это предварительная оценка: после проверки страниц и требований уточню объём работ и согласую условия.</p>\n <div class=\"pp-price-grid\">\n  <div class=\"pp-price\"><small>Стоимость</small><strong>от 5 000 ₽</strong><p>Начальная оценка простой выгрузки; окончательная сумма зависит от состава задачи.</p></div>\n  <div class=\"pp-price\"><small>Срок</small><strong>от 3 рабочих дней</strong><p>Отсчёт после согласования источников, полей и условий доступа к данным.</p></div>\n </div>\n <p class=\"pp-lead\">На стоимость влияют три основных фактора:</p>\n <div class=\"pp-factors\">\n  <div class=\"pp-factor\"><h3>Источники и их структура</h3><p>Количество сайтов, тип страниц, различия в карточках и наличие технических ограничений.</p></div>\n  <div class=\"pp-factor\"><h3>Объём и состав каталога</h3><p>Число позиций, набор собираемых полей, варианты товаров и правила очистки данных.</p></div>\n  <div class=\"pp-factor\"><h3>Логика обновления</h3><p>Разовая выгрузка или расписание, история изменений, сопоставление одинаковых товаров и формат отчёта.</p></div>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Рабочий процесс</div><h2>Как делаю: четыре этапа <span class=\"pp-gradient\">от проверки до передачи</span></h2>\n <p class=\"pp-lead\">До разработки определяем, какие сведения нужны и как вы будете ими пользоваться. Это помогает не собирать лишние данные и не усложнять инструмент без необходимости.</p>\n <div class=\"pp-steps\">\n  <article class=\"pp-step\"><h3>Разбираю задачу</h3><p>Получаю адреса сайтов или примеры карточек, список нужных полей и желаемый формат результата. Уточняю, какие товары нужно сопоставлять.</p></article>\n  <article class=\"pp-step\"><h3>Проверяю источники</h3><p>Изучаю структуру страниц, доступность информации и частоту изменений. На этом этапе выявляются ограничения, которые могут повлиять на сроки и состав решения.</p></article>\n  <article class=\"pp-step\"><h3>Разрабатываю и тестирую</h3><p>Настраиваю получение информации, обработку значений и формирование выгрузки. Проверяю результат на согласованных примерах, исправляю ошибки обработки.</p></article>\n  <article class=\"pp-step\"><h3>Передаю результат</h3><p>Подготавливаю файлы и инструкцию, показываю тестовую таблицу. При необходимости отдельно обсуждаем запуск по расписанию и дальнейшее сопровождение.</p></article>\n </div>\n <div class=\"pp-note\"><div style=\"font-size:19px;line-height:1\">!</div><div><strong>Условия сбора:</strong> работаю с информацией, доступной на выбранных страницах, с учётом правил и ограничений источника. Обход авторизации, CAPTCHA и технических защит не включается в стандартную задачу.</div></div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Пример постановки задачи</div><h2>Как может выглядеть <span class=\"pp-gradient\">результат</span></h2>\n <p class=\"pp-lead\">Ниже — условный пример для иллюстрации процесса, а не описание выполненного проекта или отзыв заказчика.</p>\n <div class=\"pp-example\">\n  <article><strong>БЫЛО</strong><p>Сотруднику приходится открывать страницы магазинов по очереди, вручную переписывать цены и затем сводить значения в одну таблицу. При повторной проверке трудно заметить, что изменилось.</p></article>\n  <article><strong>СДЕЛАЛ</strong><p>Для выбранных страниц настраивается сбор названия товара, ссылки, цены и даты проверки. Значения приводятся к единому формату и выгружаются в Excel или CSV.</p></article>\n  <article><strong>СТАЛО</strong><p>Вместо разрозненных записей появляется общая таблица, которую можно сортировать, фильтровать и использовать для сравнения предложений. Фактическая автоматизация зависит от доступности источников.</p></article>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Частые вопросы</div><h2>Что важно знать <span class=\"pp-gradient\">перед заказом</span></h2>\n <div class=\"pp-faq\">\n  <details><summary>Можно собирать цены сразу с нескольких сайтов?</summary><p>Да, если страницы и данные доступны для обработки. Источники проверяются отдельно, поскольку структура карточек и правила отображения цены могут различаться. Количество сайтов учитывается при расчёте.</p></details>\n  <details><summary>Какие поля можно включить в выгрузку?</summary><p>Обычно это название товара, ссылка, цена, артикул, наличие, характеристики, продавец и дата проверки. Точный набор зависит от информации на странице. Перед разработкой согласуем список, чтобы таблица содержала нужные данные, а не лишние колонки.</p></details>\n  <details><summary>В каком формате я получу результат?</summary><p>Для таблиц подойдут Excel или CSV. Для передачи в другую программу можно согласовать JSON или иной формат с учётом того, где будут использоваться данные.</p></details>\n  <details><summary>Можно настроить регулярное обновление цен?</summary><p>Можно предусмотреть запуск по расписанию, если это допускают источник и выбранная инфраструктура. Частота проверок согласуется заранее: слишком частые запросы могут создавать нагрузку и приводить к ограничениям со стороны сайта.</p></details>\n  <details><summary>Что нужно прислать для расчёта стоимости?</summary><p>Достаточно отправить ссылки на несколько типовых страниц, список нужных полей и пример того, как должна выглядеть итоговая таблица. По этим материалам можно проверить структуру источников, определить возможные ограничения и назвать более точную цену и срок.</p></details>\n </div>\n <div class=\"pp-related\">\n  <p>Для постоянного отслеживания изменений пригодится услуга <a href=\"/services/monitoring-cen-konkurentov/\">мониторинг цен конкурентов</a>. Когда нужно свести предложения в общий отчёт, можно дополнить сбор <a href=\"/services/tablica-sravneniya-cen-konkurentov/\">таблицей сравнения цен конкурентов</a>. Если цены размещены в кабинетах и каталогах поставщиков, отдельно рассмотрим <a href=\"/services/parsing-cen-postavshchikov/\">парсинг цен поставщиков</a>.</p>\n  <p>Все направления разработки собраны на странице <a href=\"/services/\">«Услуги»</a>.</p>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-final\"><div class=\"pp-label\">Обсудим задачу</div><h2>Нужен <span class=\"pp-gradient\">парсер цен</span>?</h2><p>Пришлите ссылки на сайты и напишите, какие товары и параметры требуется собирать. Я проверю источники, предложу состав выгрузки и обозначу стоимость и срок до начала разработки.</p><div class=\"pp-actions\" style=\"justify-content:center\"><a class=\"pp-btn\" href=\"tel:+79641519362\">Позвонить: +7 (964) 151-93-62 ↗</a><a class=\"pp-btn pp-btn-ghost\" href=\"https://t.me/+79641519362\">Написать в Telegram</a></div><div class=\"pp-contact\"><span>Телефон: <a href=\"tel:+79641519362\">+7 (964) 151-93-62</a></span><span>Email: <a href=\"mailto:tochka_rosta24@list.ru\">tochka_rosta24@list.ru</a></span></div></div>\n</div></section>\n</div>\n\n<script type=\"application/ld+json\">\n{\n \"@context\":\"https://schema.org\",\n \"@graph\":[\n  {\n   \"@type\":\"Service\",\n   \"@id\":\"https://ipkorotkov.online/services/parser-cen/#service\",\n   \"name\":\"Разработка парсера цен\",\n   \"serviceType\":\"Сбор и мониторинг цен товаров с сайтов\",\n   \"url\":\"https://ipkorotkov.online/services/parser-cen/\",\n   \"description\":\"Разработка парсера для сбора цен товаров с выбранных сайтов с подготовкой выгрузки Excel или CSV.\",\n   \"provider\":{\"@type\":\"Person\",\"name\":\"Константин Коротков\"},\n   \"areaServed\":{\"@type\":\"Country\",\"name\":\"Россия\"},\n   \"offers\":{\"@type\":\"Offer\",\"price\":\"5000\",\"priceCurrency\":\"RUB\",\"description\":\"Начальная ориентировочная стоимость простой задачи\"}\n  },\n  {\n   \"@type\":\"FAQPage\",\n   \"@id\":\"https://ipkorotkov.online/services/parser-cen/#faq\",\n   \"mainEntity\":[\n    {\"@type\":\"Question\",\"name\":\"Можно собирать цены сразу с нескольких сайтов?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Да, если страницы и данные доступны для обработки. Каждый источник проверяется отдельно; количество источников учитывается в оценке стоимости и срока.\"}},\n    {\"@type\":\"Question\",\"name\":\"Какие поля можно включить в выгрузку?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Обычно это название товара, ссылка, цена, артикул, наличие, характеристики, продавец и дата проверки. Точный набор зависит от информации на странице.\"}},\n    {\"@type\":\"Question\",\"name\":\"В каком формате я получу результат?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Для таблиц подойдут Excel или CSV. Для передачи в другую программу можно обсудить JSON или иной согласованный формат.\"}},\n    {\"@type\":\"Question\",\"name\":\"Можно настроить регулярное обновление цен?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Можно предусмотреть запуск по расписанию, если это допускают источник и выбранная инфраструктура. Частота проверок согласуется заранее.\"}},\n    {\"@type\":\"Question\",\"name\":\"Что нужно прислать для расчёта стоимости?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Нужно отправить ссылки на несколько типовых страниц, список нужных полей и пример итоговой таблицы. По этим материалам проверяются источники и уточняются цена и срок.\"}}\n   ]\n  }\n ]\n}\n</script>\n<!-- /wp:html -->','Парсер цен','Разработка парсера цен для автоматического сбора стоимости товаров, мониторинга цен конкурентов и сравнения предложений интернет-магазинов.','inherit','closed','closed','','575-revision-v1','','','2026-11-23 06:53:32','2026-11-23 06:53:32','',575,'https://ipkorotkov.online/?p=625',0,'revision','',0),(626,1,'2026-11-23 07:01:30','2026-11-23 07:01:30','<!-- wp:html -->\n<style>\n.pp-github{--pp-ink:#080b14;--pp-ink2:#0c1120;--pp-sur:#121a2e;--pp-sur2:#18233c;--pp-line:#243352;--pp-line2:#33456b;--pp-tx:#eaf0fb;--pp-mut:#a9b8d5;--pp-lime:#b6f24a;--pp-cyan:#2dd4f7;--pp-blue:#6d9bff;--pp-violet:#b18cff;--pp-g:linear-gradient(100deg,var(--pp-lime),var(--pp-cyan) 42%,var(--pp-blue) 72%,var(--pp-violet));background:var(--pp-ink);color:var(--pp-tx);font:16px/1.72 \'Manrope\',Arial,sans-serif;width:min(96vw,1480px);max-width:1480px;margin:0;padding:0 0 1px;position:relative;left:50%;transform:translateX(-50%);isolation:isolate;overflow:hidden}\n.pp-github *{box-sizing:border-box}\n.pp-github a{color:var(--pp-cyan);text-decoration:none}\n.pp-github a:hover{color:var(--pp-lime);text-decoration:underline;text-underline-offset:4px}\n.pp-github .pp-wrap{width:100%;max-width:1360px;margin:0 auto;padding:0 34px}\n.pp-github .pp-hero{position:relative;padding:64px 0 58px;background:radial-gradient(ellipse at 12% 10%,rgba(182,242,74,.13),transparent 35%),radial-gradient(ellipse at 90% 18%,rgba(109,155,255,.18),transparent 38%),linear-gradient(145deg,#0c1120,#080b14 65%);border-bottom:1px solid var(--pp-line)}\n.pp-github .pp-hero:before{content:\"\";position:absolute;inset:0;pointer-events:none;opacity:.42;background-image:linear-gradient(rgba(109,155,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(109,155,255,.07) 1px,transparent 1px);background-size:48px 48px;mask-image:radial-gradient(ellipse at 50% 20%,#000 15%,transparent 78%)}\n.pp-github .pp-hero-in{position:relative;z-index:1;max-width:1180px}\n.pp-github .pp-eyebrow{display:inline-flex;align-items:center;gap:10px;color:var(--pp-lime);font:700 11px/1.4 \'JetBrains Mono\',monospace;letter-spacing:.16em;text-transform:uppercase;margin:0 0 18px}\n.pp-github .pp-eyebrow:before{content:\"\";width:25px;height:2px;background:var(--pp-g);display:inline-block}\n.pp-github .pp-gradient{background:var(--pp-g);-webkit-background-clip:text;background-clip:text;color:transparent}\n.pp-github .pp-intro{font-size:clamp(17px,1.65vw,21px);color:var(--pp-mut);max-width:1080px;margin:0 0 27px}\n.pp-github .pp-actions{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 25px}\n.pp-github .pp-btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:14px 22px;border-radius:13px;background:var(--pp-g);color:#08130a!important;font-weight:900;box-shadow:0 10px 30px rgba(109,155,255,.22);transition:.2s}\n.pp-github .pp-btn:hover{transform:translateY(-3px);text-decoration:none;box-shadow:0 14px 36px rgba(109,155,255,.34)}\n.pp-github .pp-btn-ghost{background:transparent;color:var(--pp-tx)!important;border:1px solid var(--pp-line2);box-shadow:none}\n.pp-github .pp-btn-ghost:hover{border-color:var(--pp-lime);color:var(--pp-lime)!important}\n.pp-github .pp-chips{display:flex;gap:8px;flex-wrap:wrap}\n.pp-github .pp-chip{font:600 11px \'JetBrains Mono\',monospace;color:var(--pp-mut);padding:7px 11px;border:1px solid var(--pp-line2);border-radius:99px;background:rgba(18,26,46,.7)}\n.pp-github .pp-chip strong{color:var(--pp-lime);font-weight:700}\n.pp-github .pp-section{padding:58px 0;border-bottom:1px solid var(--pp-line);position:relative}\n.pp-github .pp-section:nth-child(odd){background:linear-gradient(180deg,rgba(18,26,46,.35),rgba(8,11,20,0))}\n.pp-github .pp-label{color:var(--pp-lime);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.15em;text-transform:uppercase;margin:0 0 12px}\n.pp-github h2{font-family:\'Onest\',Arial,sans-serif;font-size:clamp(25px,3vw,37px);font-weight:900;letter-spacing:-.025em;line-height:1.15;color:var(--pp-tx);margin:0 0 16px}\n.pp-github h3{font-family:\'Onest\',Arial,sans-serif;font-size:19px;font-weight:800;letter-spacing:-.02em;line-height:1.25;color:var(--pp-tx);margin:0 0 9px}\n.pp-github .pp-lead{color:var(--pp-mut);font-size:16px;max-width:1060px;margin:0 0 27px}\n.pp-github .pp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}\n.pp-github .pp-card{position:relative;overflow:hidden;background:linear-gradient(150deg,var(--pp-sur),#0d1425);border:1px solid var(--pp-line);border-radius:17px;padding:25px 24px;min-height:190px;transition:.2s}\n.pp-github .pp-card:hover{transform:translateY(-3px);border-color:var(--pp-line2);box-shadow:0 18px 45px rgba(0,0,0,.3)}\n.pp-github .pp-card:before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--pp-accent,var(--pp-cyan))}\n.pp-github .pp-card p,.pp-github .pp-step p{color:var(--pp-mut);font-size:14px;margin:0}\n.pp-github .pp-num{font:800 12px \'JetBrains Mono\',monospace;color:var(--pp-accent,var(--pp-lime));margin:0 0 14px;letter-spacing:.12em}\n.pp-github .pp-card .pp-icon{width:41px;height:41px;border-radius:12px;display:grid;place-items:center;background:rgba(109,155,255,.12);color:var(--pp-accent,var(--pp-cyan));font-size:21px;margin:0 0 14px}\n.pp-github .pp-data{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px 16px;margin:23px 0 0;padding:0;list-style:none}\n.pp-github .pp-data li{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:11px;padding:13px 15px 13px 40px;position:relative;color:var(--pp-tx);font-size:14px}\n.pp-github .pp-data li:before{content:\"✓\";position:absolute;left:15px;top:12px;color:var(--pp-lime);font-weight:900}\n.pp-github .pp-price-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:23px 0}\n.pp-github .pp-price{padding:24px;border:1px solid var(--pp-line2);border-radius:16px;background:linear-gradient(145deg,#111b30,#0b1120)}\n.pp-github .pp-price small{display:block;color:var(--pp-mut);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.12em;text-transform:uppercase;margin-bottom:9px}\n.pp-github .pp-price strong{display:block;color:var(--pp-lime);font:900 clamp(25px,3vw,36px)/1.2 \'Onest\',Arial,sans-serif}\n.pp-github .pp-price p{font-size:13px;color:var(--pp-mut);margin:9px 0 0}\n.pp-github .pp-factors{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;counter-reset:factor}\n.pp-github .pp-factor{counter-increment:factor;padding:18px 19px;border:1px solid var(--pp-line);border-radius:13px;background:rgba(18,26,46,.65)}\n.pp-github .pp-factor:before{content:\"0\" counter(factor);display:block;color:var(--pp-cyan);font:800 12px \'JetBrains Mono\',monospace;margin-bottom:9px}\n.pp-github .pp-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;counter-reset:ppstep}\n.pp-github .pp-step{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:15px;padding:21px;counter-increment:ppstep}\n.pp-github .pp-step:before{content:\"0\" counter(ppstep);display:block;font:900 25px \'Onest\',sans-serif;background:var(--pp-g);-webkit-background-clip:text;background-clip:text;color:transparent;margin:0 0 12px}\n.pp-github .pp-example{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:22px}\n.pp-github .pp-example article{padding:20px;border:1px solid var(--pp-line);border-radius:14px;background:var(--pp-sur)}\n.pp-github .pp-example strong{display:block;color:var(--pp-lime);font:700 11px \'JetBrains Mono\',monospace;letter-spacing:.1em;margin-bottom:9px}\n.pp-github .pp-example p{color:var(--pp-mut);font-size:14px;margin:0}\n.pp-github .pp-note{display:flex;gap:13px;align-items:flex-start;background:rgba(255,194,71,.07);border:1px solid rgba(255,194,71,.35);border-radius:13px;padding:16px 18px;margin:22px 0 0;color:var(--pp-mut);font-size:13.5px}\n.pp-github .pp-note strong{color:#ffc247}\n.pp-github .pp-faq{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.pp-github .pp-faq details{background:var(--pp-sur);border:1px solid var(--pp-line);border-radius:13px;padding:17px 19px}\n.pp-github .pp-faq summary{cursor:pointer;font:800 15px/1.4 \'Onest\',Arial,sans-serif;color:var(--pp-cyan)}\n.pp-github .pp-faq details p{font-size:14px;color:var(--pp-mut);margin:12px 0 0}\n.pp-github .pp-bottom-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);gap:18px;align-items:stretch}\n.pp-github .pp-related{padding:27px 25px;border:1px solid var(--pp-line);border-radius:16px;background:rgba(18,26,46,.72);color:var(--pp-mut)}\n.pp-github .pp-related h3{color:var(--pp-lime);margin:0 0 16px}\n.pp-github .pp-related ul{margin:0;padding-left:20px}\n.pp-github .pp-related li{margin:0 0 13px;color:var(--pp-mut)}\n.pp-github .pp-related li:last-child{margin-bottom:0}\n.pp-github .pp-final{height:100%;padding:34px 30px;text-align:left;border:1px solid var(--pp-line2);border-radius:19px;background:radial-gradient(ellipse at 20% 0%,rgba(182,242,74,.12),transparent 40%),linear-gradient(140deg,#0c1120,#121a2e 55%,#1a1638);box-shadow:0 22px 65px rgba(0,0,0,.24)}\n.pp-github .pp-final h2{font-size:clamp(27px,3.2vw,40px)}\n.pp-github .pp-final p{max-width:none;margin:0 0 22px;color:var(--pp-mut)}\n.pp-github .pp-final .pp-actions{justify-content:flex-start!important}\n.pp-github .pp-contact{display:flex;justify-content:flex-start;gap:12px 17px;flex-wrap:wrap;margin-top:19px;font:600 13px \'JetBrains Mono\',monospace;color:var(--pp-mut)}\n.pp-github .pp-contact a{color:var(--pp-tx);border-bottom:1px dashed var(--pp-cyan)}\n@media(max-width:900px){.pp-github .pp-wrap{padding:0 22px}.pp-github .pp-steps{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:900px){.pp-github .pp-bottom-grid{grid-template-columns:1fr}}\n@media(max-width:650px){.pp-github .pp-wrap{padding:0 16px}.pp-github .pp-hero{padding:42px 0 38px}.pp-github .pp-section{padding:42px 0}.pp-github .pp-grid,.pp-github .pp-steps,.pp-github .pp-faq,.pp-github .pp-price-grid,.pp-github .pp-factors,.pp-github .pp-example{grid-template-columns:1fr}.pp-github .pp-data{grid-template-columns:1fr}.pp-github .pp-card{min-height:0}.pp-github .pp-final{padding:35px 18px}}\n@media(prefers-reduced-motion:reduce){.pp-github *{transition:none!important}}\n</style>\n\n<div class=\"pp-github\">\n<section class=\"pp-hero\">\n <div class=\"pp-wrap\"><div class=\"pp-hero-in\">\n  <div class=\"pp-eyebrow\">Сбор данных · сравнение · автоматизация</div>\n  <p class=\"pp-intro\">Парсер цен автоматически собирает стоимость товаров с выбранных сайтов, чтобы сравнивать предложения без постоянной ручной проверки. Разработаю сбор данных под ваши источники и подготовлю результат в Excel или CSV либо в формате для дальнейшей обработки.</p>\n  <div class=\"pp-actions\"><a class=\"pp-btn\" href=\"tel:+79641519362\">Обсудить задачу <span>↗</span></a><a class=\"pp-btn pp-btn-ghost\" href=\"https://t.me/+79641519362\">Написать в Telegram</a></div>\n  <div class=\"pp-chips\"><span class=\"pp-chip\"><strong>01</strong> Сбор цен</span><span class=\"pp-chip\"><strong>02</strong> Сопоставление товаров</span><span class=\"pp-chip\"><strong>03</strong> Excel / CSV</span><span class=\"pp-chip\">Удалённая работа по России</span></div>\n </div></div>\n</section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Результат разработки</div><h2>Что получите после разработки <span class=\"pp-gradient\">парсера цен</span></h2>\n <p class=\"pp-lead\">До начала работ согласуем поля и правила обработки. Итоговые данные будут готовы для анализа в таблице или передачи в другую программу.</p>\n <div class=\"pp-grid\">\n  <article class=\"pp-card\" style=\"--pp-accent:#b6f24a\"><div class=\"pp-num\">01 / ИНСТРУМЕНТ</div><div class=\"pp-icon\">⌘</div><h3>Рабочий сборщик</h3><p>Программа или скрипт, настроенный на согласованные сайты, категории или список товарных страниц. Способ запуска и требования к окружению описываются при передаче.</p></article>\n  <article class=\"pp-card\" style=\"--pp-accent:#2dd4f7\"><div class=\"pp-num\">02 / ВЫГРУЗКА</div><div class=\"pp-icon\">▤</div><h3>Таблица с данными</h3><p>Файл Excel или CSV с названием товара, ссылкой, ценой, артикулом, наличием и другими согласованными полями. Лишние и пустые значения можно отфильтровать.</p></article>\n  <article class=\"pp-card\" style=\"--pp-accent:#b18cff\"><div class=\"pp-num\">03 / ПЕРЕДАЧА</div><div class=\"pp-icon\">✓</div><h3>Проверка и пояснения</h3><p>Тестовая выгрузка для сверки, описание основных настроек и рекомендации по запуску. Если требуется регулярный сбор, отдельно согласуем порядок обновления.</p></article>\n </div>\n <ul class=\"pp-data\"><li>Название и URL товара</li><li>Текущая и прежняя цена, если доступны</li><li>Артикул или код позиции</li><li>Характеристики и варианты товара</li><li>Наличие или статус предложения</li><li>Магазин или название источника</li><li>Дата и время получения данных</li><li>Поля для сопоставления аналогов</li></ul>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Бюджет и сроки</div><h2>Цена и срок разработки <span class=\"pp-gradient\">парсера цен</span></h2>\n <p class=\"pp-lead\">Для простой задачи с одним доступным источником ориентир — от 5 000 ₽ и от 3 рабочих дней. Это предварительная оценка: после проверки страниц и требований уточню объём работ и согласую условия.</p>\n <div class=\"pp-price-grid\">\n  <div class=\"pp-price\"><small>Стоимость</small><strong>от 5 000 ₽</strong><p>Начальная оценка простой выгрузки; окончательная сумма зависит от состава задачи.</p></div>\n  <div class=\"pp-price\"><small>Срок</small><strong>от 3 рабочих дней</strong><p>Отсчёт после согласования источников, полей и условий доступа к данным.</p></div>\n </div>\n <p class=\"pp-lead\">На стоимость влияют три основных фактора:</p>\n <div class=\"pp-factors\">\n  <div class=\"pp-factor\"><h3>Источники и их структура</h3><p>Количество сайтов, тип страниц, различия в карточках и наличие технических ограничений.</p></div>\n  <div class=\"pp-factor\"><h3>Объём и состав каталога</h3><p>Число позиций, набор собираемых полей, варианты товаров и правила очистки данных.</p></div>\n  <div class=\"pp-factor\"><h3>Логика обновления</h3><p>Разовая выгрузка или расписание, история изменений, сопоставление одинаковых товаров и формат отчёта.</p></div>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Рабочий процесс</div><h2>Как делаю: четыре этапа <span class=\"pp-gradient\">от проверки до передачи</span></h2>\n <p class=\"pp-lead\">До разработки определяем, какие сведения нужны и как вы будете ими пользоваться. Это помогает не собирать лишние данные и не усложнять инструмент без необходимости.</p>\n <div class=\"pp-steps\">\n  <article class=\"pp-step\"><h3>Разбираю задачу</h3><p>Получаю адреса сайтов или примеры карточек, список нужных полей и желаемый формат результата. Уточняю, какие товары нужно сопоставлять.</p></article>\n  <article class=\"pp-step\"><h3>Проверяю источники</h3><p>Изучаю структуру страниц, доступность информации и частоту изменений. На этом этапе выявляются ограничения, которые могут повлиять на сроки и состав решения.</p></article>\n  <article class=\"pp-step\"><h3>Разрабатываю и тестирую</h3><p>Настраиваю получение информации, обработку значений и формирование выгрузки. Проверяю результат на согласованных примерах, исправляю ошибки обработки.</p></article>\n  <article class=\"pp-step\"><h3>Передаю результат</h3><p>Подготавливаю файлы и инструкцию, показываю тестовую таблицу. При необходимости отдельно обсуждаем запуск по расписанию и дальнейшее сопровождение.</p></article>\n </div>\n <div class=\"pp-note\"><div style=\"font-size:19px;line-height:1\">!</div><div><strong>Условия сбора:</strong> работаю с информацией, доступной на выбранных страницах, с учётом правил и ограничений источника. Обход авторизации, CAPTCHA и технических защит не включается в стандартную задачу.</div></div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Пример постановки задачи</div><h2>Как может выглядеть <span class=\"pp-gradient\">результат</span></h2>\n <p class=\"pp-lead\">Ниже — условный пример для иллюстрации процесса, а не описание выполненного проекта или отзыв заказчика.</p>\n <div class=\"pp-example\">\n  <article><strong>БЫЛО</strong><p>Сотруднику приходится открывать страницы магазинов по очереди, вручную переписывать цены и затем сводить значения в одну таблицу. При повторной проверке трудно заметить, что изменилось.</p></article>\n  <article><strong>СДЕЛАЛ</strong><p>Для выбранных страниц настраивается сбор названия товара, ссылки, цены и даты проверки. Значения приводятся к единому формату и выгружаются в Excel или CSV.</p></article>\n  <article><strong>СТАЛО</strong><p>Вместо разрозненных записей появляется общая таблица, которую можно сортировать, фильтровать и использовать для сравнения предложений. Фактическая автоматизация зависит от доступности источников.</p></article>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-label\">Частые вопросы</div><h2>Что важно знать <span class=\"pp-gradient\">перед заказом</span></h2>\n <div class=\"pp-faq\">\n  <details><summary>Можно собирать цены сразу с нескольких сайтов?</summary><p>Да, если страницы и данные доступны для обработки. Источники проверяются отдельно, поскольку структура карточек и правила отображения цены могут различаться. Количество сайтов учитывается при расчёте.</p></details>\n  <details><summary>Какие поля можно включить в выгрузку?</summary><p>Обычно это название товара, ссылка, цена, артикул, наличие, характеристики, продавец и дата проверки. Точный набор зависит от информации на странице. Перед разработкой согласуем список, чтобы таблица содержала нужные данные, а не лишние колонки.</p></details>\n  <details><summary>В каком формате я получу результат?</summary><p>Для таблиц подойдут Excel или CSV. Для передачи в другую программу можно согласовать JSON или иной формат с учётом того, где будут использоваться данные.</p></details>\n  <details><summary>Можно настроить регулярное обновление цен?</summary><p>Можно предусмотреть запуск по расписанию, если это допускают источник и выбранная инфраструктура. Частота проверок согласуется заранее: слишком частые запросы могут создавать нагрузку и приводить к ограничениям со стороны сайта.</p></details>\n  <details><summary>Что нужно прислать для расчёта стоимости?</summary><p>Достаточно отправить ссылки на несколько типовых страниц, список нужных полей и пример того, как должна выглядеть итоговая таблица. По этим материалам можно проверить структуру источников, определить возможные ограничения и назвать более точную цену и срок.</p></details>\n </div>\n</div></section>\n\n<section class=\"pp-section\"><div class=\"pp-wrap\">\n <div class=\"pp-bottom-grid\">\n  <div class=\"pp-final\"><div class=\"pp-label\">Связь по проекту</div><h2>Нужен <span class=\"pp-gradient\">парсер под вашу задачу</span>?</h2><p>Напишите в Telegram или позвоните. Обсудим источники, поля для выгрузки и формат результата. После проверки страниц согласуем стоимость и срок.</p><div class=\"pp-actions\"><a class=\"pp-btn\" href=\"https://t.me/+79641519362\">Написать в Telegram ↗</a><a class=\"pp-btn pp-btn-ghost\" href=\"tel:+79641519362\">+7 (964) 151-93-62</a></div><div class=\"pp-contact\"><span>Email: <a href=\"mailto:tochka_rosta24@list.ru\">tochka_rosta24@list.ru</a></span></div></div>\n  <div class=\"pp-related\"><h3>Смежные услуги</h3><ul>\n   <li><a href=\"/services/monitoring-cen-konkurentov/\">Мониторинг цен конкурентов</a></li>\n   <li><a href=\"/services/parser-marketplace/\">Парсер маркетплейсов</a></li>\n   <li><a href=\"/services/vygruzka-bazy-organizaciy-excel/\">Выгрузка базы организаций в Excel</a></li>\n  </ul><p style=\"margin:19px 0 0\">Другие направления: <a href=\"/services/\">все услуги</a>.</p></div>\n </div>\n</div></section>\n</div>\n\n<script type=\"application/ld+json\">\n{\n \"@context\":\"https://schema.org\",\n \"@graph\":[\n  {\n   \"@type\":\"Service\",\n   \"@id\":\"https://ipkorotkov.online/services/parser-cen/#service\",\n   \"name\":\"Разработка парсера цен\",\n   \"serviceType\":\"Сбор и мониторинг цен товаров с сайтов\",\n   \"url\":\"https://ipkorotkov.online/services/parser-cen/\",\n   \"description\":\"Разработка парсера для сбора цен товаров с выбранных сайтов с подготовкой выгрузки Excel или CSV.\",\n   \"provider\":{\"@type\":\"Person\",\"name\":\"Константин Коротков\"},\n   \"areaServed\":{\"@type\":\"Country\",\"name\":\"Россия\"},\n   \"offers\":{\"@type\":\"Offer\",\"price\":\"5000\",\"priceCurrency\":\"RUB\",\"description\":\"Начальная ориентировочная стоимость простой задачи\"}\n  },\n  {\n   \"@type\":\"FAQPage\",\n   \"@id\":\"https://ipkorotkov.online/services/parser-cen/#faq\",\n   \"mainEntity\":[\n    {\"@type\":\"Question\",\"name\":\"Можно собирать цены сразу с нескольких сайтов?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Да, если страницы и данные доступны для обработки. Каждый источник проверяется отдельно; количество источников учитывается в оценке стоимости и срока.\"}},\n    {\"@type\":\"Question\",\"name\":\"Какие поля можно включить в выгрузку?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Обычно это название товара, ссылка, цена, артикул, наличие, характеристики, продавец и дата проверки. Точный набор зависит от информации на странице.\"}},\n    {\"@type\":\"Question\",\"name\":\"В каком формате я получу результат?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Для таблиц подойдут Excel или CSV. Для передачи в другую программу можно обсудить JSON или иной согласованный формат.\"}},\n    {\"@type\":\"Question\",\"name\":\"Можно настроить регулярное обновление цен?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Можно предусмотреть запуск по расписанию, если это допускают источник и выбранная инфраструктура. Частота проверок согласуется заранее.\"}},\n    {\"@type\":\"Question\",\"name\":\"Что нужно прислать для расчёта стоимости?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Нужно отправить ссылки на несколько типовых страниц, список нужных полей и пример итоговой таблицы. По этим материалам проверяются источники и уточняются цена и срок.\"}}\n   ]\n  }\n ]\n}\n</script>\n<!-- /wp:html -->','Парсер цен','Разработка парсера цен для автоматического сбора стоимости товаров, мониторинга цен конкурентов и сравнения предложений интернет-магазинов.','inherit','closed','closed','','575-revision-v1','','','2026-11-23 07:01:30','2026-11-23 07:01:30','',575,'https://ipkorotkov.online/?p=626',0,'revision','',0),(630,1,'2026-11-23 08:24:15','2026-11-23 08:24:15',' ','','','publish','closed','closed','','630','','','2026-11-23 08:24:15','2026-11-23 08:24:15','',0,'https://ipkorotkov.online/?p=630',5,'nav_menu_item','',0),(631,1,'2026-11-23 08:25:44','2026-11-23 08:25:44','<!-- wp:html -->\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"ProfessionalService\",\n  \"name\": \"Программист\",\n  \"image\": \"https://ipkorotkov.online/wp-content/uploads/2026/11/browser_1217683.png\",\n  \"url\": \"https://ipkorotkov.online/contact/\",\n  \"telephone\": \"+7-964-151-93-62\",\n  \"email\": \"tochka_rosta24@list.ru\",\n  \"address\": {\n    \"@type\": \"PostalAddress\",\n    \"streetAddress\": \"Орехово, 9-46\",\n    \"addressLocality\": \"Нерехта\",\n    \"addressRegion\": \"Костромская область\",\n    \"postalCode\": \"157800\",\n    \"addressCountry\": \"RU\"\n  },\n  \"geo\": {\n    \"@type\": \"GeoCoordinates\",\n    \"latitude\": 57.4470,\n    \"longitude\": 40.5750\n  },\n  \"openingHoursSpecification\": [\n    {\n      \"@type\": \"OpeningHoursSpecification\",\n      \"dayOfWeek\": [\"Monday\",\"Tuesday\",\"Wednesday\",\"Thursday\",\"Friday\",\"Saturday\",\"Sunday\"],\n      \"opens\": \"07:00\",\n      \"closes\": \"19:00\"\n    }\n  